const cookies = [
 {name:'Chocolate Chunk',type:'signature',desc:'Brown butter base with semi-sweet chocolate chips, dark chocolate chunks, topped with sea salt flakes.',img:'https://images.unsplash.com/photo-1673551490160-3f2e712b9373?auto=format&fit=crop&w=1600&q=85',credit:'American Heritage Chocolate / Unsplash',source:'https://unsplash.com/photos/chocolate-chip-cookies-and-a-glass-of-milk-tqKB97R-eOw'},
 {name:'Biscoff',type:'signature',desc:'Brown butter base with Biscoff cookie pieces, white chocolate chips, drizzled with Biscoff spread.',img:'https://assets-eu-01.kc-usercontent.com/21d2ecef-fb9b-01b1-9022-cf60b52c2c77/d79e9c4f-6fbe-4c62-8ca7-fe295e3169b3/Biscoff-Cookies-WEB-RES-1.jpg?auto=format&lossless=1&q=85&w=1200',credit:'Silver Spoon',source:'https://www.silverspoon.co.uk/recipes/biscoff-cookies'},
 {name:'Chocolate Sea Salt Toffee',type:'signature',desc:'Rich brown butter cookie with toffee bits, semi-sweet chocolate chips, topped with sea salt flakes.',img:'https://scientificallysweet.com/wp-content/uploads/2022/09/IMG_3198-salted-toffee-chocolate-chip-cookies-feature2.jpg',credit:'Scientifically Sweet',source:'https://scientificallysweet.com/salted-toffee-chocolate-chip-cookies/'},
 {name:'Red Velvet',type:'signature',desc:'Red cookie base with cocoa powder, white chocolate chips and white chocolate drizzle.',img:'https://sallysbakingaddiction.com/wp-content/uploads/2013/12/red-velvet-white-chocolate-chip-cookies-2.jpg',credit:'Sally’s Baking',source:'https://sallysbakingaddiction.com/red-velvet-chocolate-chip-cookies/'},
 {name:'Pumpkin Chocolate Chip',type:'seasonal',desc:'Brown butter base with pumpkin purée, cinnamon, and chocolate chips.',img:'https://sallysbakingaddiction.com/wp-content/uploads/2013/09/chewy-pumpkin-chocolate-chip-cookies-3.jpg',credit:'Sally’s Baking',source:'https://sallysbakingaddiction.com/2013/09/04/pumpkin-chocolate-chip-cookies/'},
 {name:'Maple Pecan',type:'seasonal',desc:'Brown butter base with cinnamon, maple syrup, pecans.',img:'https://confessionsofabakingqueen.com/wp-content/uploads/2020/11/plate-of-maple-pecan-cookies-1-of-1-1024x1536-1.jpg',credit:'Confessions of a Baking Queen',source:'https://confessionsofabakingqueen.com/maple-pecan-cookies/'}
];
const $=s=>document.querySelector(s);const quantities=cookies.map(()=>0);const prices={4:14,6:20,12:38};let box=4;let requestText='';
$('#hero-photo').src=cookies[0].img;$('#about-photo').src=cookies[2].img;
$('#cookie-grid').innerHTML=cookies.map((c,i)=>`<article class="cookie-card" data-type="${c.type}"><div class="cookie-image"><img src="${c.img}" alt="Illustrative photograph of ${c.name} cookies" loading="lazy" decoding="async"><span class="cookie-tag ${c.type}">${c.type==='seasonal'?'OCTOBER SPECIAL':'SIGNATURE'}</span></div><h3>${c.name}</h3><p>${c.desc}</p><div class="cookie-bottom"><span>${c.type==='seasonal'?'A little taste of fall':'A forever favorite'}</span><button type="button" class="add-cookie" data-add="${i}" aria-label="Add ${c.name} to your box">+</button></div></article>`).join('');
$('#flavor-choices').innerHTML=cookies.map((c,i)=>`<div class="flavor-choice"><img src="${c.img}" alt="" loading="lazy" decoding="async"><label for="flavor-${i}">${c.name}</label><select id="flavor-${i}" data-quantity="${i}" aria-label="${c.name} quantity">${Array.from({length:13},(_,n)=>`<option value="${n}">${n}</option>`).join('')}</select></div>`).join('');
$('#photo-credits').innerHTML=cookies.map(c=>`<a href="${c.source}" target="_blank" rel="noreferrer">${c.name} — ${c.credit} ↗</a>`).join('');
function update(){const count=quantities.reduce((a,b)=>a+b,0);$('#selection-count').textContent=`${count} / ${box} selected`;$('.selection-progress').setAttribute('aria-valuemax',box);$('.selection-progress').setAttribute('aria-valuenow',Math.min(count,box));$('#selection-progress-fill').style.width=`${Math.min(count/box,1)*100}%`;$('#clear-box').disabled=count===0;$('#summary-total').textContent=`$${prices[box]}`;$('#summary-size').textContent=`${box} cookies · Mix & match`;$('#summary-items').replaceChildren();cookies.forEach((c,i)=>{const select=$(`#flavor-${i}`);select.value=quantities[i];Array.from(select.options).forEach(o=>o.disabled=Number(o.value)>Math.max(quantities[i],box-(count-quantities[i])));if(quantities[i]){const row=document.createElement('div');row.className='summary-line';const name=document.createElement('span');name.textContent=c.name;const qty=document.createElement('strong');qty.textContent=`× ${quantities[i]}`;row.append(name,qty);$('#summary-items').append(row)}});if(!count)$('#summary-items').innerHTML='<p>Your favorites go here.<br>Pick a flavor to get started.</p>';$('#flavor-error').textContent=count>box?`Your box has ${count} cookies. Remove ${count-box} to fit your selected size.`:'';}
document.querySelectorAll('[data-quantity]').forEach(s=>s.addEventListener('change',()=>{quantities[Number(s.dataset.quantity)]=Number(s.value);update()}));
$('#box-size').addEventListener('change',e=>{box=Number(e.target.value);update()});
function boxFeedback(message){$('#box-feedback span').textContent=message;$('#box-feedback').hidden=false;}
$('#box-feedback button').addEventListener('click',()=>$('#box-feedback').hidden=true);
$('#box-feedback a').addEventListener('click',()=>$('#box-feedback').hidden=true);
$('#clear-box').addEventListener('click',()=>{quantities.fill(0);update()});
document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{if(quantities.reduce((a,b)=>a+b,0)<box){const i=Number(b.dataset.add);quantities[i]++;update();boxFeedback(`${cookies[i].name} added · ${quantities.reduce((a,b)=>a+b,0)}/${box} cookies`)}else{boxFeedback('Your box is full. View your box to change the size or flavors.')}}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.cookie-card').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.type!==b.dataset.filter)}));
$('#nav-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#nav-toggle').setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('#nav-toggle').setAttribute('aria-expanded','false')}));
function minimumDate(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const v=t=>parts.find(p=>p.type===t).value;const d=new Date(`${v('year')}-${v('month')}-${v('day')}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+7);return d.toISOString().slice(0,10)}
$('#pickup-time').insertAdjacentHTML('beforeend',Array.from({length:19},(_,i)=>{const h=10+Math.floor(i/2),m=i%2?'30':'00',label=`${h>12?h-12:h}:${m} ${h>=12?'PM':'AM'}`;return `<option value="${String(h).padStart(2,'0')}:${m}">${label}</option>`}).join(''));
$('#pickup-date').min=minimumDate();$('#pickup-date').addEventListener('focus',()=>$('#pickup-date').min=minimumDate());
document.querySelectorAll('.dialog-close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#credits-open').addEventListener('click',()=>$('#credits-dialog').showModal());
$('#order-form').addEventListener('submit',e=>{e.preventDefault();const count=quantities.reduce((a,b)=>a+b,0);if(count!==box){$('#flavor-error').textContent=`Please choose exactly ${box} cookies. You currently have ${count}.`;$('#flavor-0').focus();return}const d=new FormData(e.target);if(!Array.from($('#pickup-time').options).some(o=>o.value&&o.value===d.get('time'))){$('#pickup-time').focus();return}if(d.get('date')<minimumDate()){$('#pickup-date').setCustomValidity('Please allow at least one week from today.');$('#pickup-date').reportValidity();return}$('#pickup-date').setCustomValidity('');requestText=`Hello Pasha! I’d like to request a cookie box.\n\n${box} cookies — $${prices[box]}\n${cookies.map((c,i)=>quantities[i]?`${quantities[i]} × ${c.name}`:'').filter(Boolean).join('\n')}\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nOccasion: ${d.get('occasion')}\nPreferred pickup: ${d.get('date')} (${d.get('time')} Eastern time)\nPayment preference: ${d.get('payment')}\nNotes: ${d.get('notes')||'None'}\n\nI have read the allergy and cancellation notices. I understand availability and pickup are subject to confirmation, and the address will be sent on pickup day. Please confirm the total and payment instructions. Thank you!`;$('#review-title').textContent='Your cookie request';$('#review-content').textContent=requestText;$('#send-email').href=`mailto:pashabakess@gmail.com?subject=${encodeURIComponent('Cookie order request — '+d.get('name'))}&body=${encodeURIComponent(requestText)}`;$('#copy-status').textContent='';$('#review-dialog').showModal()});
$('#pickup-date').addEventListener('input',()=>$('#pickup-date').setCustomValidity(''));
$('#copy-request').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(requestText);$('#copy-status').textContent='Copied. Paste into an email to pashabakess@gmail.com.'}catch{$('#copy-status').textContent='Copy unavailable. Select and copy the request above.'}});
function enquiry(general){$('#enquiry-title').textContent=general?'Say hello to Pasha':'Plan a celebration';$('#enquiry-type').value=general?'General question':'Birthday / celebration';$('#enquiry-dialog').showModal()}
$('#event-open').addEventListener('click',()=>enquiry(false));$('#contact-open').addEventListener('click',()=>enquiry(true));$('#large-order-open').addEventListener('click',()=>{enquiry(false);$('#enquiry-type').value='Large order'});
$('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);requestText=`Hello Pasha!\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nType: ${d.get('type')}\nDate: ${d.get('date')||'Not decided'}\nQuantity: ${d.get('quantity')}\n\n${d.get('message')}`;$('#review-title').textContent='Your enquiry';$('#review-content').textContent=requestText;$('#send-email').href=`mailto:pashabakess@gmail.com?subject=${encodeURIComponent(d.get('type')+' enquiry')}&body=${encodeURIComponent(requestText)}`;$('#copy-status').textContent='';$('#enquiry-dialog').close();$('#review-dialog').showModal()});

update();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_cookie_box',title:'Configure a cookie box',description:'Set the visible box size and flavor quantities. Does not send an order or collect payment.',inputSchema:{type:'object',properties:{size:{type:'integer',enum:[4,6,12]},quantities:{type:'array',items:{type:'integer',minimum:0,maximum:12},minItems:6,maxItems:6}},required:['size','quantities'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||![4,6,12].includes(input.size)||!Array.isArray(input.quantities)||input.quantities.length!==6||input.quantities.some(v=>!Number.isInteger(v)||v<0||v>12)||input.quantities.reduce((a,b)=>a+b,0)>input.size)throw new Error('Use a box of 4, 6, or 12 and six nonnegative flavor counts within capacity.');box=input.size;input.quantities.forEach((v,i)=>quantities[i]=v);$('#box-size').value=box;update();return {size:box,quantities:[...quantities],price:prices[box],status:'configured; not submitted'}}})).catch(()=>{})}catch{}}

